export function YouTubeProjects() {
  const { language } = useContext(LanguageContext);
  const t = COPY[language];
  return (
    <section className="container-max pb-28" aria-labelledby="youtube-projects-title" dir={language === "ar" ? "rtl" : undefined}>
      <div className="eyebrow">YouTube</div>
      <h2 id="youtube-projects-title" className="h2-section mb-4">{t.title}</h2>
      <p className="lead mb-10 max-w-[680px]">{t.intro}</p>
      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {CHANNELS.map((channel) => (
          <article key={channel.handle} className="glass overflow-hidden rounded-3xl border border-border">
            <a href={channel.href} target="_blank" rel="noopener noreferrer" aria-label={`${channel.name}: ${t.link}`} className="block aspect-video bg-black/30 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-accent">
              <Image src={channel.image} alt={`${channel.name} (${channel.handle})`} width={channel.width} height={channel.height} sizes="(min-width: 1024px) 50vw, 100vw" className="block h-full w-full object-contain" />
            </a>
            <div className="p-6 md:p-8">
              <p className="font-mono text-xs text-accent mb-3" dir="ltr">{channel.handle}</p>
              <h3 className="text-2xl font-semibold text-white mb-3">{channel.name}</h3>
              <p className="text-muted leading-relaxed mb-6">{t[channel.key]}</p>
              <a href={channel.href} target="_blank" rel="noopener noreferrer" className="inline-flex min-h-11 items-center font-semibold text-accent underline underline-offset-4 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-accent">{t.link} ↗</a>
            </div>
          </article>
        ))}
      </div>
      <p className="mt-5 text-sm text-muted">{t.note}</p>
    </section>
  );
      }
